const ROOT = new URL('./', self.location.href);
const PREFIX = `sanguo-offline:${ROOT.pathname}:`;
const CACHE = PREFIX + CONFIG.version;
const entries = new Map(CONFIG.entries.map(entry => [new URL(entry.url, ROOT).href, entry]));
let downloading = null;
let lastError = '';

async function store(cache, url) {
  if (await cache.match(url)) return;
  const response = await fetch(url, { cache: 'reload', signal: AbortSignal.timeout(60000) });
  if (!response.ok || response.type === 'opaque') throw new Error('资源下载失败，请联网后重试');
  await cache.put(url, response);
}

async function status() {
  const cache = await caches.open(CACHE);
  const saved = new Set((await cache.keys()).map(request => request.url));
  let done = 0, bytes = 0;
  for (const [url, entry] of entries) if (saved.has(url)) { done++; bytes += entry.bytes; }
  return { type: 'sanguo:offline', version: CONFIG.version, done, bytes,
    total: entries.size, totalBytes: CONFIG.entries.reduce((sum, entry) => sum + entry.bytes, 0),
    complete: done === entries.size, downloading: !!downloading, error: lastError };
}

async function broadcast() {
  const data = await status();
  for (const client of await self.clients.matchAll({ type: 'window' })) client.postMessage(data);
}

self.addEventListener('install', event => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE);
    // 安装成功即具备页面、坐标与远景；大体积近景由玩家主动下载。
    for (const file of CONFIG.essential) await store(cache, new URL(file, ROOT).href);
    if (!self.registration.active) await self.skipWaiting();
  })());
});

self.addEventListener('activate', event => {
  event.waitUntil((async () => {
    // 更新等待旧页面关闭后才生效；仅清理本站点目录自己的旧版资源。
    for (const name of await caches.keys()) if (name.startsWith(PREFIX) && name !== CACHE) await caches.delete(name);
    await self.clients.claim();
  })());
});

self.addEventListener('fetch', event => {
  if (event.request.method !== 'GET') return;
  const url = new URL(event.request.url);
  if (url.origin !== ROOT.origin) return;
  url.search = ''; url.hash = '';
  if (url.href === ROOT.href) url.pathname += 'index.html';
  if (!entries.has(url.href)) return;
  event.respondWith((async () => {
    const cache = await caches.open(CACHE);
    const saved = await cache.match(url.href);
    if (saved) return saved;
    const response = await fetch(event.request);
    if (response.ok && response.type !== 'opaque') {
      // 配额不足时仍交付网络响应；完整下载会明确报告失败。
      event.waitUntil(cache.put(url.href, response.clone()).catch(() => {}));
    }
    return response;
  })());
});

async function download() {
  lastError = '';
  try {
    const cache = await caches.open(CACHE);
    const queue = [...entries.keys()];
    let next = 0, finished = 0, failed = false;
    await Promise.all(Array.from({ length: 2 }, async () => {
      while (next < queue.length && !failed) {
        const url = queue[next++];
        try { await store(cache, url); }
        catch (error) {
          failed = true;
          lastError = error.name === 'QuotaExceededError'
            ? '浏览器空间不足，离线资源未下载完整。腾出空间后可继续下载。'
            : '下载中断，离线资源未下载完整。联网后可继续下载。';
        }
        if (++finished % 12 === 0 || failed) await broadcast();
      }
    }));
  } finally { downloading = null; await broadcast(); }
}

self.addEventListener('message', event => {
  if (!['sanguo:offline-status', 'sanguo:offline-download'].includes(event.data?.type)) return;
  if (event.data.type === 'sanguo:offline-download' && !downloading) downloading = download();
  event.waitUntil((async () => {
    event.ports[0]?.postMessage(await status());
    if (downloading) await downloading;
  })());
});
